1	import { Request, Response } from "express";
2	import { trace, SpanKind } from "@opentelemetry/api";
3	import { createShapeId } from "@tldraw/tlschema";
4	import { getOrCreateRoom } from "./rooms.js";
5	import { slugifyTableName, tableNameFromSlug } from "../shared/slugify.js";
6	import { ensurePlayerArea, pageIdOf, nextIndex, mtgCardShape, addCommanderDamageCounters } from "./tableFurniture.js";
7	import { MAX_SEATS, CARD_W, CARD_H, commandZoneCardPosition } from "./cardLayout.js";
8	import { validateIncomingEvent } from "./contractValidation.js";
9	import { subscribeToSpine } from "./spineSubscriber.js";
10	import { dispatchSpineEvent } from "./spineEventDispatch.js";
11	
12	const tracer = trace.getTracer("mtg-tabletop");
13	
14	/** A commander riding seat.joined (ticket 18) — always face up, no `face` field on the wire. */
15	interface SeatJoinedCommander {
16	  card: { scryfallId: string; instanceId: string };
17	  cardName: string;
18	  frontImageUrl: string;
19	  backImageUrl: string | null;
20	}
21	
22	/** A ghost's identity never collides with a real instanceId — instanceAlreadyOnTable (cardArrival.ts) matches exact strings. */
23	const ghostInstanceId = (instanceId: string): string => `ghost:${instanceId}`;
24	
25	
26	interface SeatJoinedPayload {
27	  deckName: string;
28	  playmatImageUrl?: string;
29	  cardBackImageUrl?: string;
30	  sleeveColor?: string;
31	  primaryColor?: string;
32	  secondaryColor?: string;
33	  commanders?: SeatJoinedCommander[];
34	  gameCardIndex?: number;
35	}
36	
37	export async function handleSeatJoined(req: Request, res: Response): Promise<void> {
38	  const tableName = slugifyTableName(req.params.tableName ?? "");
39	  if (!tableName) {
40	    res.status(400).json({ error: "table name required" });
41	    return;
42	  }
43	
44	  const result = validateIncomingEvent<SeatJoinedPayload>(req.body, "seat.joined");
45	  if (!result.ok) {
46	    res.status(400).json({ error: result.error });
47	    return;
48	  }
49	  const { envelope } = result;
50	  if (slugifyTableName(envelope.tableId) !== tableName) {
51	    res.status(400).json({ error: "envelope tableId does not match the table being posted to" });
52	    return;
53	  }
54	  const seatId = envelope.initiator.seatId;
55	  if (!seatId) {
56	    res.status(400).json({ error: "initiator.seatId is required for seat.joined" });
57	    return;
58	  }
59	  const { playerName } = envelope.initiator;
60	  const { deckName, playmatImageUrl, cardBackImageUrl, sleeveColor, primaryColor, secondaryColor, commanders } = envelope.payload;
61	
62	  trace.getActiveSpan()?.setAttributes({
63	    "event.id": envelope.id,
64	    "event.name": envelope.name,
65	    "table.name": tableNameFromSlug(tableName),
66	    "table.slug": tableName,
67	    "seat.id": seatId,
68	    "player.name": playerName,
69	  });
70	
71	  const entry = getOrCreateRoom(tableName);
72	
73	  // One live Spine SSE subscription per room, opened the first time a seat.joined
74	  // tells this room its Spine tableId — a second seat joining is a no-op here.
75	  if (!entry.spineSubscription) {
76	    entry.spineTableId = envelope.tableId;
77	    entry.spineSubscription = subscribeToSpine(envelope.tableId, (spineEvent) => dispatchSpineEvent(tableName, spineEvent));
78	  }
79	
80	  if (entry.seenEventIds.has(envelope.id)) {
81	    trace.getActiveSpan()?.setAttribute("seat_joined.deduped", "event-id");
82	    res.status(200).json({ ok: true, deduped: true });
83	    return;
84	  }
85	  if (entry.seats.has(seatId)) {
86	    entry.seenEventIds.add(envelope.id);
87	    trace.getActiveSpan()?.setAttribute("seat_joined.deduped", "seat-already-seated");
88	    res.status(200).json({ ok: true, deduped: true });
89	    return;
90	  }
91	
92	  if (entry.seats.size >= MAX_SEATS) {
93	    trace.getActiveSpan()?.setAttribute("seat_joined.rejected", "table-full");
94	    res.status(409).json({ error: `table is full: ${MAX_SEATS} seats` });
95	    return;
96	  }
97	
98	  const pageId = pageIdOf(entry);
99	  const seatCommanders = commanders ?? [];
100	
101	  await tracer.startActiveSpan(
102	    "add player furniture",
103	    {
104	      kind: SpanKind.INTERNAL,
105	      attributes: {
106	        "event.id": envelope.id,
107	        "event.name": envelope.name,
108	        "table.name": tableNameFromSlug(tableName),
109	        "table.slug": tableName,
110	        "seat.id": seatId,
111	        "player.name": playerName,
112	        "player.deckName": deckName,
113	        "player.playmatImageUrl": playmatImageUrl ?? "",
114	        "player.cardBackImageUrl": cardBackImageUrl ?? "",
115	        "player.sleeveColor": sleeveColor ?? "",
116	        "player.primaryColor": primaryColor ?? "",
117	        "player.secondaryColor": secondaryColor ?? "",
118	        "commander.count": seatCommanders.length,
119	        "commander.names": seatCommanders.map((commander) => commander.cardName),
120	        "room.seats_before": entry.seats.size,
121	      },
122	    },
123	    async (span) => {
124	      try {
125	        const playerArea = await ensurePlayerArea(entry, pageId, seatId, playerName, {
126	          deckName,
127	          playmatImageUrl,
128	          cardBackImageUrl,
129	          sleeveColor,
130	          primaryColor,
131	          secondaryColor,
132	        });
133	
134	        if (seatCommanders.length > 0) {
135	          await entry.room.updateStore((store) => {
136	            seatCommanders.forEach((commander, slot) => {
137	              const { instanceId } = commander.card;
138	              const position = commandZoneCardPosition(playerArea.seatIndex, slot, seatCommanders.length as 1 | 2);
139	              const sharedFields = {
140	                pageId,
141	                x: position.x,
142	                y: position.y,
143	                w: CARD_W,
144	                h: CARD_H,
145	                scryfallId: commander.card.scryfallId,
146	                cardName: commander.cardName,
147	                frontImageUrl: commander.frontImageUrl,
148	                backImageUrl: commander.backImageUrl,
149	                face: "front" as const,
150	                faceDown: false,
151	                sleeveColor: playerArea.sleeveColor ?? null,
152	                cardBackImageUrl: playerArea.cardBackImageUrl ?? null,
153	                owner: seatId,
154	                isCommander: true,
155	              };
156	
157	              store.put(
158	                mtgCardShape({
159	                  id: createShapeId(`ghost-${instanceId}`),
160	                  index: nextIndex(tableName),
161	                  instanceId: ghostInstanceId(instanceId),
162	                  isLocked: true,
