51	/** Relative luminance (0 dark … 1 light) of a #rrggbb hex, sRGB-weighted. */
52	function luminance(hex: string): number {
53	  const n = parseInt(hex.slice(1), 16);
54	  const r = (n >> 16) & 0xff;
55	  const g = (n >> 8) & 0xff;
56	  const b = n & 0xff;
57	  return (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
58	}
