60	/**
61	 * The darker of the deck's two identity colors, for the deck-title text. Both are optional
62	 * (an older Shuffler may send neither); with one or none present, fall back to the house
63	 * dark chrome token so the title stays on-brand and legible.
64	 */
65	export function darkerColor(a?: string, b?: string): string {
66	  if (a && b) return luminance(a) <= luminance(b) ? a : b;
67	  return a ?? b ?? DEFAULT_TITLE_COLOR;
