232	export async function ensurePlayerArea(
233	  entry: RoomEntry,
234	  pageId: string,
235	  seatId: string,
236	  playerName: string,
237	  look: PlayerAreaLook = {}
238	): Promise<PlayerArea> {
239	  const existing = entry.seats.get(seatId);
240	  if (existing) return existing;
241	
242	  const seatIndex = entry.seats.size;
243	  const area: PlayerArea = {
244	    seatIndex,
245	    playerName,
246	    playmatImageUrl: look.playmatImageUrl,
247	    cardBackImageUrl: look.sleeveColor ? undefined : look.cardBackImageUrl,
248	    sleeveColor: look.sleeveColor,
