271	  const exileId = createShapeId(`region-exile-${entry.tableName}-${seatId}`);
272	  const labelId = createShapeId(`name-label-${entry.tableName}-${seatId}`);
273	  const lifeCounterId = createShapeId(`life-counter-${entry.tableName}-${seatId}`);
