275	  await entry.room.updateStore((store) => {
276	    store.put(
277	      zoneShape({
278	        id: matId,
279	        pageId,
280	        x: mat.x,
281	        y: mat.y,
282	        w: mat.w,
283	        h: mat.h,
284	        label: "",
285	        index: nextFurnitureIndex(entry.tableName),
286	        zone: "playmat",
287	        seatId,
288	        imageUrl: look.playmatImageUrl,
289	      })
290	    );
291	
292	    store.put(
293	      zoneShape({
294	        id: libraryId,
295	        pageId,
296	        x: library.x,
297	        y: library.y,
298	        w: library.w,
