400	        w: PLAYMAT_W - LIFE_COUNTER_W - GAP,
401	        h: NAME_LABEL_HEIGHT,
402	        text: look.deckName ? `${playerName} 〜 ${look.deckName}` : playerName,
403	        color: darkerColor(look.primaryColor, look.secondaryColor),
404	      },
405	      meta: {},
406	    } as any);
407	  });
408	
409	  await ensureStackDrawn(entry, pageId);
410	
411	  trace.getActiveSpan()?.setAttributes({
412	    "seat.id": seatId,
413	    "player.name": playerName,
414	    "seat.index": seatIndex,
415	    "playmat.image_present": Boolean(look.playmatImageUrl),
416	    "card_back.image_present": Boolean(area.cardBackImageUrl),
417	    "sleeve.present": Boolean(area.sleeveColor),
