423	export async function ensureStackDrawn(entry: RoomEntry, pageId: string): Promise<void> {
424	  if (entry.seats.size === 0) return;
425	  const bounds = stackBounds();
426	  const stackId = createShapeId(`region-stack-${entry.tableName}`);
427	  await entry.room.updateStore((store) => {
428	    if (store.get(stackId)) return;
429	    store.put(
430	      zoneShape({
431	        id: stackId,
432	        pageId,
433	        x: bounds.x,
434	        y: bounds.y,
435	        w: bounds.w,
436	        h: bounds.h,
437	        label: "The Stack",
