import { describe, it, expect, beforeAll, afterAll } from "vitest";
import type { Server } from "node:http";
import { randomUUID } from "node:crypto";
import { startServer } from "../src/server/server";
import { getRoomRegistry } from "../src/server/rooms";
import { slugFor } from "./support/tableSlug";
import {
  playmatBounds,
  libraryBounds,
  commandZoneBounds,
  graveyardBounds,
  exileBounds,
  stackBounds,
  commandZoneCardPosition,
  lifeCounterPosition,
  commanderDamageCounterPosition,
} from "../src/server/cardLayout";

let server: Server;
let port: number;

beforeAll(async () => {
  server = await startServer(0);
  const address = server.address();
  if (typeof address === "object" && address) port = address.port;
});

afterAll(() => {
  server.close();
});

function fakeTraceparent(): string {
  return `00-${randomUUID().replace(/-/g, "")}-${randomUUID().replace(/-/g, "").slice(0, 16)}-01`;
}

let eventCounter = 0;
function seatJoined(tableName: string, envelopeOverrides: Record<string, unknown> = {}, payloadOverrides: Record<string, unknown> = {}) {
  eventCounter++;
  return {
    id: randomUUID(),
    tableId: slugFor(tableName),
    name: "seat.joined",
    occurredAt: new Date().toISOString(),
    initiator: { seatId: `seat-${eventCounter}`, playerName: "Jess" },
    occurredIn: "shuffler",
    origin: "shuffler.shuffleUp",
    significance: "administrative",
    traceparent: fakeTraceparent(),
    schemaVersion: 1,
    payload: {
      deckName: "Blame Game",
      playmatImageUrl: "https://example.com/playmat.png",
      cardBackImageUrl: "https://example.com/card-back.jpg",
      ...payloadOverrides,
    },
    ...envelopeOverrides,
  };
}

async function post(tableName: string, body: unknown): Promise<Response> {
  return fetch(`http://localhost:${port}/api/tables/${slugFor(tableName)}/events`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
  });
}

function shapesOf(tableName: string) {
  const entry = getRoomRegistry().get(slugFor(tableName));
  if (!entry) return [];

