  await page.mouse.up();

  await expect(page.locator(cardLocator(instanceIdA))).not.toBeAttached({ timeout: 5000 });
  await expect(page.locator(cardLocator(instanceIdB))).not.toBeAttached({ timeout: 5000 });
});

